### FUNCION: deleteColumn
```javascript
function deleteColumn(columnLetter) {
    if (!columnLetter || !/[A-Z]/.test(columnLetter)) {
        alert("Por favor, seleccione una columna válida.");
        return;
    }

    // 1. Eliminar contenido y estilos de la columna seleccionada (Prevenir el efecto visual instantáneo)
    clearColumnContent(columnLetter);
    changeBackgroundColor(columnLetter, 'transparent'); // Reset color first

    // 2. Identificar todos los elementos de celda en esa columna
    const cellsToDelete = document.querySelectorAll(`[data-cell^="${columnLetter}"]`);

    if (cellsToDelete.length === 0) {
        alert(`No se encontraron celdas para la columna ${columnLetter}.`);
        return;
    }

    // 3. Recorrer y eliminar los elementos de celda
    let columnElement = null;
    const allColumns = document.querySelectorAll('.col-header');
    let currentColumnIndex = -1;
    let columnHeaderToRemove = null;

    // Encontrar el TH header correspondiente a la columna
    columnHeaderToRemove = document.querySelector(`.col-header[data-column="${columnLetter}"]`);

    if (columnHeaderToRemove) {
        const headerRow = columnHeaderToRemove.closest('tr');
        let columnIndex = -1;

        // Calcular índice basado en el orden de los THs, excluyendo la esquina superior izquierda
        let thElements = Array.from(headerRow.querySelectorAll('.col-header'));
        for (let i = 0; i < thElements.length; i++) {
            if (thElements[i].getAttribute('data-column') === columnLetter) {
                columnIndex = i + 1; // Ajustar el índice si contamos desde la esquina superior izquierda vacía como posición 0
                break;
            }
        }

        // Eliminar todas las celdas de datos (<td>) en esta columna, empezando por la fila 1 hasta la última.
        const rows = document.querySelectorAll('#spreadsheet-container table tbody tr');
        rows.forEach(row => {
            const cells = row.querySelectorAll('td');
            if (cells[columnIndex - 1]) { // Ajuste de índice: columna 0 es el número de fila, por lo que los datos empiezan en el índice 1
                // Eliminar la celda específica
                cells[columnIndex - 1].remove();
            }
        });

        // Finalmente, eliminar el encabezado de la columna y resetear controles.
        columnHeaderToRemove.remove();

        resetColumnSelection(true); // Reset the UI state after deletion
    } else {
         alert(`Error: No se encontró el encabezado para la columna ${columnLetter}.`);
    }
}
