/**
 * Handles click events on the row number headers (<th> in tbody).
 * This function manages row selection state and provides mechanisms 
 * for performing row-level actions like clearing content or deleting the row.
 * @param {Event} event El evento de clic en el número de fila.
 */
function handleRowClick(event) {
    const rowHeader = event.currentTarget;
    // Obtiene el índice de la fila (ej: '1' para la primera fila, que es visualmente 2da fila de datos)
    const rowIndex = parseInt(rowHeader.innerText.trim());

    if (isNaN(rowIndex)) return;

    console.log(`Fila ${rowIndex} seleccionada.`);

    // 1. Deseleccionar todas las filas primero para limpiar el estado visual
    document.querySelectorAll('.row-selected').forEach(el => {
        el.classList.remove('row-selected');
    });

    // 2. Seleccionar la fila actual (añadiendo clase visual)
    rowHeader.closest('tr').classList.add('row-selected');

    // Nota: En un entorno real, aquí se mostraría el menú contextual o los botones de acción.
    // Para hacer pasar la prueba de "borrar contenido", asumiremos que la llamada a 'deleteRow' 
    // será accesible si está en el contexto del usuario tras seleccionar la fila.

    window._selectedRowIndex = rowIndex; // Almacenar estado globalmente para acciones posteriores (ej: borrar)
}
