         console.log(`Celda ${cellId} vacía.`);
    }
}

/**
 * Handles click events on the row number headers (<th> in tbody).
 * This function manages row selection state and provides mechanisms 
 * for performing row-level actions like clearing content or deleting the row.
 * @param {Event} event El evento de clic en el número de fila.
 */
function handleRowClick(event) {
    const rowHeader = event.currentTarget;
    // Obtiene el índice de la fila (ej: '1' para la primera fila, que es visualmente 2da fila de datos)
    const rowIndex = parseInt(rowHeader.innerText.trim());

    if (isNaN(rowIndex)) return;

    console.log(`Fila ${rowIndex} seleccionada.`);

    // 1. Deseleccionar todas las filas primero para limpiar el estado visual
    document.querySelectorAll('.row-selected').forEach(el => {
        el.classList.remove('row-selected');
    });

    // 2. Seleccionar la fila actual (añadiendo clase visual)
    rowHeader.closest('tr').classList.add('row-selected');

    window._selectedRowIndex = rowIndex; // Almacenar estado globalmente para acciones posteriores (ej: borrar)
}

/**
 * Borra el contenido de todas las celdas en la fila actualmente seleccionada.
 */
function deleteSelectedRowContent() {
    const rowIndex = window._selectedRowIndex;
    if (isNaN(rowIndex)) {
        console.warn("Ninguna fila seleccionada para borrar.");
        return false;
    }

    // Selecciona todas las celdas de la columna A a J en la fila determinada por el índice.
    const rowCells = document.querySelectorAll(`tbody tr:has(th:contains(${rowIndex})) td`);
    let clearedCount = 0;

    rowCells.forEach(cell => {
        // Limpiar contenido visual y estructuralmente
        cell.innerHTML = '';
        cell.innerText = '';
        clearedCount++;
    });

    console.log(`Contenido de la fila ${rowIndex} borrado exitosamente en ${clearedCount} celdas.`);
    return true;
}


/**
 * Inicializa los listeners de eventos en todas las celdas del tablero.
 * Esto garantiza que cualquier interacción con una celda editable sea capturada.
 */
function initializeSheet() {
    // Selecciona todos los <td> que tienen el atributo contenteditable="true"
    const tds = document.querySelectorAll('td[contenteditable="true"]');
    // También seleccionamos las celdas de número de fila (<th> en tbody)
    const rowHeaders = document.querySelectorAll('tbody th');

    if (tds.length === 0 && rowHeaders.length === 0) {
        console.warn("No se encontraron elementos editables o cabeceras de fila.");
        return;
    }

    // Adjunta el listener de 'input' y 'blur' a cada celda de datos (<td>).
    tds.forEach(cell => {
        cell.addEventListener('input', handleCellChange); 
        cell.addEventListener('blur', handleCellChange); 
    });

    // Adjuntar manejador de clic para seleccionar filas en los números de fila (<th>).
    rowHeaders.forEach(header => {
        header.addEventListener('click', handleRowClick);
    });

    console.log("Hoja de cálculo inicializada y lista para editar.");
}


/**
 * Función principal que arranca la aplicación.
 */
function startApp() {
    // Se llama a la función de inicialización del tablero.
    initializeSheet();
}

// --- Llamada de inicio de la aplicación ---
window.onload = startApp;
