### FUNCION: selectRowHandler
```js
function selectRowHandler(event) {
    // El evento se dispara en el TH de número de fila (columna 1).
    const rowElement = event.target.closest('tr');
    if (!rowElement) return;

    // Obtener el índice de la fila (el número visible, que es también su data-row-index)
    const rowIndex = rowElement.dataset.rowIndex || null; 

    if (rowIndex === null) {
        console.warn("No se pudo determinar el índice de la fila.");
        return;
    }

    // 1. Deseleccionar todas las filas previamente seleccionadas
    document.querySelectorAll('.row-selector').forEach(el => el.style.backgroundColor = '');
    document.getElementById('spreadsheet-container').querySelectorAll('td, th').forEach(cell => {
        cell.classList.remove('selected');
    });

    // 2. Seleccionar la fila actual (marcando el selector y todas las celdas)
    event.target.style.backgroundColor = '#cce0ff'; // Color de selección suave
    rowElement.querySelector('.row-selector').style.backgroundColor = '#cce0ff';

    // Marcar todas las celdas de la fila como seleccionadas para que el estilo CSS funcione
    const cellsInRow = rowElement.querySelectorAll('td, th');
    cellsInRow.forEach(cell => {
        cell.classList.add('selected');
    });

    // 3. Actualizar los controles y habilitar/deshabilitar botones
    updateControls(rowIndex);
}
```

