    const rowNumberText = selectedTH.innerText;
    const rowIndex = parseInt(rowNumberText);

    // 1. Encontrar la fila completa (<tr>) usando el índice
    const targetRow = document.querySelector(`tbody tr:nth-child(${rowIndex})`);

    if (!targetRow) {
