function toggleColumnVisibility(letter) {
    const allHeaders = document.querySelectorAll('.col-header');
    let headerElement = Array.from(allHeaders).find(th => th.textContent.trim().toUpperCase() === letter);

    if (!headerElement) return; // Column not found

    // 1. Determine current state (is it currently hidden?)
    const isCurrentlyHidden = headerElement.style.display === 'none';

    // 2. Toggle the display property for all relevant elements
    const cellsToShowOrHide = [headerElement, ...document.querySelectorAll(`[data-cell^="${letter}"]`)];

    cellsToShowOrHide.forEach(element => {
        if (isCurrentlyHidden) {
            element.style.display = ''; // Show it
        } else {
            element.style.display = 'none'; // Hide it
        }
    });

    // Optional: Add a class to the header itself for state management if needed, but style manipulation is sufficient here.
}
