    // 1. Check if the input is a formula
    if (newValue && newValue.startsWith("=")) {
        console.log(`[Formula detected in ${cellId}] Attempting calculation...`);
        const result = evaluateFormula(newValue);

        if (result !== null) {
            // Calculate successful: Update cell display to the result and prevent showing the formula string
            cell.innerText = result;
            console.log(`Celda ${cellId} recalculada exitosamente: ${result}`);
        } else {
            // Calculation failed, keep the formula visible (or show error)
             console.warn(`[Formula Error] Could not calculate formula in ${cellId}. Keeping original value.`);
        }
    } 
    else if (newValue !== "") {
        // Standard text/number input
        console.log(`Celda ${cellId} actualizada: "${newValue}"`);
        // NOTE: In a full app, changing any cell here would trigger recalculations in dependent cells (e.g., B4 depends on A1:A3).
    } 
    else if (newValue === "") {
         console.log(`Celda ${cellId} vacía.`);
    }
}

/**
 * Maneja el clic en un encabezado de columna (A, B, C...).
 * Alterna la visibilidad de la columna y sus celdas de datos asociadas.
 * @param {Event} event El evento click.
 */
function handleColumnHeaderClick(event) {
    const clickedElement = event.currentTarget;
    const colLetter = clickedElement.innerText.trim().toUpperCase();

    // Toggle visibility for the column header itself (the TH element in thead)
    if (clickedElement.style.display === 'none') {
        clickedElement.style.display = ''; // Show it back if it was hidden
    } else {
        clickedElement.style.display = 'none'; // Hide it now
    }

    // 1. Toggle visibility for all Data Cells in this column (A1, A2, ..., A20)
    const dataCells = document.querySelectorAll(`td[data-cell^="${colLetter}"]`);
    if (dataCells.length > 0) {
        const isHidden = dataCells[0].style.display === 'none';

        dataCells.forEach(cell => {
            // We only toggle the display property, relying on CSS to handle borders/layout adjustments if needed.
            cell.style.display = isHidden ? '' : 'none';
        });
    }
    console.log(`Column ${colLetter} visibility toggled.`);
}

/**
 * Maneja el clic en un encabezado de fila (1, 2, 3...).
 * Alterna la visibilidad de la fila y sus celdas de datos asociadas.
 * @param {Event} event El evento click.
 */
function handleRowHeaderClick(event) {
    const clickedElement = event.currentTarget;
    // The content is the row number (e.g., "1", "20")
    const rowNumberStr = clickedElement.innerText.trim(); 

    if (!rowNumberStr || isNaN(parseInt(rowNumberStr))) return; // Safety check
    const rowNumber = parseInt(rowNumberStr);

    // Toggle visibility for the row header itself (the TH element in tbody)
    if (clickedElement.style.display === 'none') {
        clickedElement.style.display = ''; // Show it back if it was hidden
    } else {
        clickedElement.style.display = 'none'; // Hide it now
    }

    // 1. Toggle visibility for all Data Cells in this row (B1, C1, ..., J1)
    // We look for data-cell attributes ending with the current row number.
    const dataCells = document.querySelectorAll(`td[data-cell$="${rowNumber}"]`);
    if (dataCells.length > 0) {
        const isHidden = dataCells[0].style.display === 'none';

        dataCells.forEach(cell => {
            // Only toggle the display property
            cell.style.display = isHidden ? '' : 'none';
        });
    }
    console.log(`Row ${rowNumber} visibility toggled.`);
}


/**
 * Inicializa los listeners de eventos en todas las celdas del tablero y sus encabezados.
 */
function initializeSheet() {
    // 1. Data Cells Listeners
    const cells = document.querySelectorAll('td[contenteditable="true"]');

    if (cells.length === 0) {
        console.warn("No se encontraron celdas editables en la hoja.");
        return;
    }

    cells.forEach(cell => {
        // Listener para captura inmediata durante la escritura
        cell.addEventListener('input', handleCellChange); 
        // Listener adicional al salir de la celda (mejor práctica)
        cell.addEventListener('blur', handleCellChange); 
    });

    // 2. Column Header Listeners (A, B, C...)
    document.querySelectorAll('.col-header').forEach(header => {
        header.addEventListener('click', handleColumnHeaderClick);
    });

    // 3. Row Header Listeners (1, 2, 3... etc.)
    document.querySelectorAll('tbody th:first-child').forEach(rowHeader => {
        // Excluye el header de la esquina superior izquierda si existiera un listener aquí
        if (!rowHeader.parentElement.tagName === 'THEAD') {
             rowHeader.addEventListener('click', handleRowHeaderClick);
        }
    });

    console.log("Hoja de cálculo inicializada y lista para editar.");
}


/**
 * Función principal que arranca la aplicación.
 */
function startApp() {
    // Se llama a la función de inicialización del tablero.
    initializeSheet();
}

// --- Llamada de inicio de la aplicación ---
window.onload = startApp;
