// Reemplaza la implementación actual en index.html con esta lógica de eventos y manejo de visibilidad.
const spreadsheetContainer = document.getElementById('spreadsheet-container');

if (spreadsheetContainer) {
    const controlsPanel = document.querySelector('#spreadsheet-controls');
    if (!controlsPanel) return;

    // Listener principal para manejar todos los botones de control de visibilidad
    controlsPanel.addEventListener('click', function(e) {
        const target = e.target;
        if (target.tagName !== 'BUTTON') return;

        const direction = target.getAttribute('data-direction');
        const identifier = target.getAttribute('data-letter') || target.getAttribute('data-number');
        let shouldHide = true; // Asumimos que el primer click es para ocultar

        // Determinar si queremos ocultar o mostrar basándose en el texto del botón (simplificado)
        if (target.textContent.includes("Mostrar")) {
            shouldHide = false;
        } else if (target.textContent.includes("Ocultar") && direction === 'column') {
             // Si es columna y dice "Ocultar", sí ocultamos (por defecto).
             shouldHide = true;
        }


        if (!identifier) return;

        if (direction === 'column') {
            const letter = identifier.toUpperCase(); // Columna A, B, C...
            // Selecciona todas las celdas que pertenecen a esa columna en el thead y tbody
            let headers = document.querySelectorAll(`.col-header[data-letter="${letter}"]`);
            let cellsToHide = [];

            if (headers.length > 0) {
                cellsToHide.push(...Array.from(headers));
            }

            // Obtener todas las celdas de datos para la columna A-J en el tbody
            const columnIndex = letter.charCodeAt(0) - 'A'.charCodeAt(0);

            if (columnIndex >= 0 && columnIndex < 10) {
                let dataCells = document.querySelectorAll(`tbody tr td:nth-child(${columnIndex + 2})`); // +2 porque el primer TH es la fila index
                dataCells.forEach(cell => cellsToHide.push(cell));

                // También ocultar los headers de columna si existen
                document.querySelectorAll(`#spreadsheet-container thead .col-header[data-letter="${letter}"]`).forEach(h => {
                    cellsToHide.push(h);
                });
            }


            if (shouldHide) {
                // Ocultar la columna completa: TH header, y todos los TD en el body
                document.querySelectorAll(`#spreadsheet-container .col-header[data-letter="${letter}"]`).forEach(el => el.style.display = 'none');

                // Iterar sobre todas las filas del tbody para ocultar la celda de datos correspondiente
                const rows = spreadsheetContainer.querySelectorAll('tbody tr');
                rows.forEach(row => {
                    // La columna es la (letter - 'A') + 2, debido al TH de índice en el primer lugar
                    const colIndex = letter.toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);
                    if (colIndex >= 0 && colIndex < 10) {
                         row.querySelector(`td:nth-child(${colIndex + 2})`).style.display = 'none';
                    }
                });

            } else {
                // Mostrar la columna completa
                document.querySelectorAll(`#spreadsheet-container .col-header[data-letter="${letter}"]`).forEach(el => el.style.display = '');

                const rows = spreadsheetContainer.querySelectorAll('tbody tr');
                rows.forEach(row => {
                    const colIndex = letter.toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);
                     if (colIndex >= 0 && colIndex < 10) {
                        row.querySelector(`td:nth-child(${colIndex + 2})`).style.display = '';
                    }
                });
            }

        } else if (direction === 'row') {
            const rowNumber = parseInt(identifier); // Fila 1, 2...
            let rowsToHide = [];

            // Buscar la fila completa en el tbody usando su contenido de texto (el TH)
            const targetRow = spreadsheetContainer.querySelector(`tbody tr th:contains(${rowNumber})`);

            if (!targetRow) {
                 // Fallback si :contains no funciona o se requiere un selector más robusto
                for(let i = 0; i < spreadsheetContainer.querySelectorAll('tbody tr').length; i++) {
                    const row = spreadsheetContainer.querySelector(`tbody tr:nth-child(${rowNumber})`);
                    if (row) {
                        targetRow = row;
                        break;
                    }
                }
            }

            if (!targetRow) return; // No se encontró la fila

            let allCellsInRow = targetRow.closest('tbody').querySelectorAll(`tr:nth-child(${rowNumber})`); 
            // Nota: La selección por :nth-child es arriesgada si el DOM cambia, pero funciona aquí porque usamos el TH de índice como referencia.

            if (shouldHide) {
                targetRow.style.display = 'none'; // Ocultar la celda de índice
                allCellsInRow.forEach(cell => cell.style.display = 'none'); // Ocultar todas las celdas de datos en esa fila
            } else {
                // Mostrar la columna/fila (solo necesitamos mostrar los elementos)
                targetRow.style.display = ''; 
                allCellsInRow.forEach(cell => cell.style.display = '');
            }
        }

    });
}
