/**
 * Sets up click listeners for row headers (row numbers) and column headers (letters).
 */
function setupHeaderListeners() {
    // 1. Row Headers Listener Setup (Handles clicking the number in the left-most TH of tbody rows)
    const rowHeaders = document.querySelectorAll('tbody th'); 
    rowHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const rowNumber = this.innerText.trim();
            // The target row is the parent TR element containing the header TH and all TDs
            const row = this.closest('tr');

            if (row) {
                // Toggle visibility of the entire row using inline style for simplicity
                const isHidden = row.style.display === 'none';
                row.style.display = isHidden ? '' : 'none';
                console.log(`Row ${rowNumber} toggled.`);
            }
        });
    });

    // 2. Column Headers Listener Setup (Handles clicking the letters in thead)
    const colHeaders = document.querySelectorAll('.col-header');
    colHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const colChar = this.innerText.trim(); // A, B, C...

            // Select all data cells (<td>) that start with the clicked column character 
            // We use a regex attribute selector approach for robustness if structure changes slightly.
            const cellsToToggle = document.querySelectorAll('td[data-cell^="' + colChar + '"]');

            let hiddenCount = 0;

            cellsToToggle.forEach(cell => {
                // Check current display state using inline style property
                if (cell.style.display === 'none' || cell.style.display === '') {
                     // If currently hidden or no style set, hide it now
                    cell.style.display = 'none'; 
                    hiddenCount++;
                } else {
                    // If visible, unhide it
                    cell.style.display = ''; 
                }
            });

             console.log(`Column ${colChar} toggled. Cells hidden/shown: ${hiddenCount}.`);
        });
    });
}
