### FUNCION: selectElement
```js
/**
 * Helper function to manage the visual selection state of rows and columns.
 * @param {HTMLElement | null} element - The element that was clicked (e.g., a row header or cell).
 */
function selectElement(element) {
    // 1. Clear previous selections
    document.querySelectorAll('.selected-row, .selected-col th, .selected-col td').forEach(el => {
        el.classList.remove('selected-row', 'selected-col');
    });

    if (!element || !element.closest('table')) return;

    // 2. Determine if it's a row selection (clicking the number header)
    const isRowHeader = element.classList.contains('row-header') && element.parentElement.tagName === 'TR';
    if (isRowHeader) {
        element.closest('tr').classList.add('selected-row');
    } 
    // 3. Determine if it's a column selection (clicking the letter header)
    else if (element.classList.contains('col-header')) {
        const colIndex = Array.from(document.querySelectorAll('.col-header')).indexOf(element);
        if (colIndex >= 0) {
            // Select all cells in this column for visual feedback
            document.querySelectorAll(`td:nth-child(${colIndex + 2}), th.col-header:nth-child(${colIndex + 2})`).forEach(el => {
                el.classList.add('selected-col');
            });
            element.closest('thead tr').classList.add('selected-col'); // Select the header row itself
        }
    } else if (element.tagName === 'TD') {
        // If clicking a data cell, select its entire row and column for convenience
        const row = element.closest('tr');
        const colIndex = Array.from(element.parentNode.children).indexOf(element);

        if (row && colIndex >= 0) {
            row.classList.add('selected-row');
             // Select the corresponding column header visually
            document.querySelectorAll(`td:nth-child(${colIndex + 2}), th.col-header:nth-child(${colIndex + 2})`).forEach(el => {
                el.classList.add('selected-col');
            });
        }
    }

    // Enable/disable buttons based on selection state
    const isRowSelected = document.querySelector('.selected-row') !== null;
    const isColSelected = document.querySelector('.selected-col').closest('th') !== null || document.querySelector('.selected-col td') !== null;

    document.getElementById('hide-row-btn').disabled = !isRowSelected;
    document.getElementById('hide-col-btn').disabled = !isColSelected;
}
