function initializeSheet() {
    const sheetBody = document.getElementById('sheet-body');
    if (!sheetBody) return;

    // --- R8 Setup: Row/Column Selection Handlers ---

    // Attach click listeners to all row number headers (<th>1</th>, <th>2</th>...)
    document.querySelectorAll('.row-header').forEach(header => {
        header.addEventListener('click', function() {
            selectElement(this);
        });
    });

    // Attach click listeners to all column letter headers (<th class="col-header">A</th>, etc.)
    document.querySelectorAll('.col-header').forEach(header => {
        header.addEventListener('click', function() {
            selectElement(this);
        });
    });

    // --- R1 Setup: Cell Change Handlers (Existing Logic) ---
    const cells = document.querySelectorAll('td[contenteditable="true"]');

    if (cells.length === 0) {
        console.warn("No se encontraron celdas editables en la hoja.");
        return;
    }

    // Adjunta el listener de 'input' y 'blur' a cada celda.
    cells.forEach(cell => {
        // Listener para captura inmediata durante la escritura
        cell.addEventListener('input', handleCellChange); 
        // Listener adicional al salir de la celda (mejor práctica)
        cell.addEventListener('blur', handleCellChange); 
    });

    console.log("Hoja de cálculo inicializada y lista para editar.");
}
